#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main(void) {
    while (1) {
        int n, m, s;
        cin >> n >> m >> s;
        if (!n && !m && !s) break;

        n *= n;
        int *dp = new int[55 * 3005]{0}; // Use a single-dimensional array
        dp[0] = 1;

        for (int i = 1; i <= m; i++) {
            int *new_dp = new int[55 * 3005]{0}; // Temporary array for current iteration
            for (int j = 0; j <= n; j++) {
                for (int k = 0; k <= s; k++) {
                    new_dp[j * 3005 + k] = dp[j * 3005 + k]; // Copy previous values
                    if (k - i >= 0 && j > 0) {
                        new_dp[j * 3005 + k] = (new_dp[j * 3005 + k] + dp[(j - 1) * 3005 + (k - i)]) % 100000;
                    }
                }
            }
            delete[] dp; // Free the previous array
            dp = new_dp; // Move to the new array
        }
        cout << dp[n * 3005 + s] << endl;

        delete[] dp; // Clean up at the end
    }
}

